create temporary table import_summary (wikidata_id text primary key, summary text not null, source text not null);

insert into import_summary (wikidata_id, summary, source) values
  ('Q141586128', 'The Cheetahmen is a video game series created by Active Enterprises starring three anthropomorphic cheetahs. It was introduced in 1991, as part of the Action 52 multi-game cartridge for the NES. It is notable for its main theme, as it was later used as the overworld music in the parody freeware game Syobon Action (also known as "Cat Mario"), as well as its extremely low quality, often being cited as one of the worst video games of all time. The Cheetahmen also appear in an unpublished sequel for the NES, Cheetahmen II, and a Sega Genesis title that was again called The Cheetahmen. Cheetahmen III was in development in 1994 for a prototype handheld console by Active Enterprises but is now considered vaporware.', 'https://en.wikipedia.org/wiki/The_Cheetahmen'),
  ('Q11331909', 'Fire Bam is an action role-playing video game developed by HAL Laboratory and Live Planning and published in 1988 by HAL Laboratory for the Famicom Disk System. It is an early example of a fast-paced action game.', 'https://en.wikipedia.org/wiki/Fire_Bam'),
  ('Q11328844', 'Kwirk, known in Japan as Puzzle Boy, is a puzzle video game developed and published by Atlus in Japan on November 24, 1989, for the Game Boy. It was the very first video game Atlus released under its own brand. The game was later published in North America in March 1990 by Acclaim Entertainment.', 'https://en.wikipedia.org/wiki/Kwirk'),
  ('Q11313863', 'Super Boy Allan is an educational video game developed by ASK Kodansha for the Family Computer Disk System, and published by Sunsoft in 1987.

Super Boy Allan is the second installment in Sunsoft and Asmik''s Intelligence Game trilogy. It is preceded by Adian no Tsue (1986), and followed by Chitei Tairiku Orudora (1987).

In the game, Allan Colada journeys from his home in the foothills into the mountains to retrieve a remedy for his sister Leela''s fever.', 'https://en.wikipedia.org/wiki/Super_Boy_Allan'),
  ('Q16966880', 'The Eggerland series consists of several puzzle games developed by HAL Laboratory. Its first release was in 1985 for MSX computer systems. The gameplay is almost exactly the same across the series, with only a few changes over the years, mainly graphical.

The hero of most games is Lolo, a blue, spherical character with eyes, arms, and legs. The story mainly deals with King Egger, the villain, capturing princess Lala, who is similar to Lolo, only colored pink or red, and wearing a bow. Lolo must rescue Lala by travelling through Egger''s domain and solving the puzzle rooms laid out before him.', 'https://en.wikipedia.org/wiki/Eggerland'),
  ('Q11501817', 'Tantei Jingūji Saburō: Shinjuku Chūō Kōen Satsujin Jiken is a 1987 adventure video game developed and published by Data East for the Famicom Disk System. It is the first of fhe Jake Hunter series.

Tantei Jingūji Saburō: Shinjuku Chūō Kōen Satsujin Jiken received a sequel titled Tantei Jingūji Saburō: Yokohama-kō Renzoku Satsujin Jiken (1988), which follows the narrative set-up by this game. The 1987 game has since been re-released in compilations, digital forms and remade for feature phones and the Nintendo DS in the 2000s.', 'https://en.wikipedia.org/wiki/Tantei_Jing%C5%ABji_Sabur%C5%8D:_Shinjuku_Ch%C5%AB%C5%8D_K%C5%8Den_Satsujin_Jiken'),
  ('Q16267624', 'DoReMikko is a music video game developed by Konami, and published for the Family Computer Disk System in 1987. The game''s title comes from the first three solfège syllables, do, re, and mi.

Konami bundled DoReMikko with a 36-key musical keyboard input device for playing and composing music. DoReMikko was one of the first video games designed for use with a musical instrument peripheral. Contemporary game releases, including the Famicom titles Otocky (1987) and Instant Musician (1987), took all input from standard gamepads.

Konami went on to create a "Game Machine Division" devoted to music video games with input devices patterned after musical instruments, or involving dance-like movement. The Game Machine Division published its first title, Beatmania, in 1997.', 'https://en.wikipedia.org/wiki/Doremikko'),
  ('Q605445', 'Sokoban is a puzzle video game created in 1981 by Hiroyuki Imabayashi. In Sokoban, the player pushes boxes in a warehouse to get them onto storage locations. The game is viewed from a top-down perspective. Boxes can only be pushed, and only one box can be pushed at a time. The principal challenge is planning moves correctly to avoid causing a deadlock, a situation where a box or the player becomes permanently trapped, making the puzzle unsolvable.

Imabayashi''s company, Thinking Rabbit, released the first commercial version in Japan in 1982. Following this debut, Thinking Rabbit and its licensed partners developed a series of new titles until 2000. The game debuted internationally in 1988 with the U.S. release Soko-Ban. Falcon, a Japanese software company, acquired the rights to Sokoban in 2001. Since then, new installments have been published either by Falcon under the Thinking Rabbit brand or by licensed partners.', 'https://en.wikipedia.org/wiki/Sokoban'),
  ('Q847977', 'The Mysterious Murasame Castle is a 1986 action-adventure game developed and published by Nintendo. It was originally released for the Family Computer Disk System exclusively in Japan as the second original game for the platform. The Mysterious Murasame Castle was later released worldwide on the Virtual Console in 2014 and for the Nintendo Classics service in 2023.', 'https://en.wikipedia.org/wiki/The_Mysterious_Murasame_Castle'),
  ('Q761452', 'Ai Senshi Nicol is a 1987 action-adventure game by Konami for the Family Computer Disk System. It was only released in Japan.', 'https://en.wikipedia.org/wiki/Ai_Senshi_Nicol'),
  ('Q935001', 'Meikyū Jiin Dababa is a 1987 action game by Konami for the Family Computer Disk System. It was only released in Japan.', 'https://en.wikipedia.org/wiki/Meiky%C5%AB_Jiin_Dababa'),
  ('Q108716718', 'Excitebike is a 1984 racing video game developed and published by Nintendo for the Nintendo Entertainment System. It was ported to arcades for the Nintendo VS. System later that year and Famicom Disk System in 1988. In North America, it became one of the best-selling games on the console. It was the first game in the Excite series.

Designed and directed by Shigeru Miyamoto, the smooth side-scrolling game engine his team developed for Excitebike was later used to develop Super Mario Bros. (1985), which had the effect of Mario smoothly accelerating from a walk to a run, rather than move at a constant speed.', 'https://en.wikipedia.org/wiki/Excitebike'),
  ('Q56345292', 'I Am a Teacher: Super Mario Sweater is a 1986 educational video game released for the Famicom Disk System in Japan. It was designed by Royal Industries, a Japanese appliance and sewing machine company, in collaboration with Nintendo. The game is designed to teach how to knit Mario-branded patterns on a sweater by hand, with the option for player made patterns to be mailed in to Royal Industries to physically produce the sweaters for purchase. Video game critics have noted that the game is an unusual entry in the Mario franchise.', 'https://en.wikipedia.org/wiki/I_Am_a_Teacher:_Super_Mario_Sweater'),
  ('Q1984732', 'Kiki Kaikai is a 1986 shoot ''em up video game developed and published by Taito for arcades. Set in Feudal Japan, the player assumes the role of a Shinto shrine maiden who must use her o-fuda scrolls and gohei wand to defeat renegade spirits and monsters from Japanese mythology. The game is noteworthy for using a traditional fantasy setting in a genre otherwise filled with science fiction motifs.

The game received a number of home ports, both as a stand-alone title and as part of compilations. Taito would license the rights of the game to Natsume, who developed a sequel for the Super NES in 1992, known as Pocky & Rocky outside Japan. The series, known as Kiki Kaikai in Japan and Pocky & Rocky outside Japan, has continued since then under Natsume Atari.', 'https://en.wikipedia.org/wiki/Kiki_Kaikai'),
  ('Q1057942', 'Super Mario Bros. is a 1985 platform game developed and published by Nintendo for the Nintendo Entertainment System (NES). Directed and produced by Shigeru Miyamoto, it is the successor to the 1983 arcade game Mario Bros. and the first game in the Super Mario series. Players control Mario, or his brother Luigi in the multiplayer mode, to traverse the Mushroom Kingdom to rescue Princess Toadstool from King Koopa (later named Bowser). They traverse side-scrolling stages while avoiding hazards such as enemies and pits and collecting power-ups such as the Super Mushroom, Fire Flower, and Starman.

Miyamoto and Takashi Tezuka designed Super Mario Bros. as a culmination of the team''s experience working on Devil World and the side-scrollers Excitebike and Kung Fu. Miyamoto wanted to create a more colorful platform game with a scrolling screen and larger characters. The team designed the first level, World 1-1, as a tutorial for platform gameplay. Koji Kondo''s soundtrack is one of the earliest in video games, making music a centerpiece of the design.', 'https://en.wikipedia.org/wiki/Super_Mario_Bros.'),
  ('Q2422991', 'Knight Lore is a 1984 action-adventure game developed and published by Ultimate Play the Game, and written by company founders Chris and Tim Stamper. The game is known for its use of isometric graphics, which it further popularized in video games. In Knight Lore, the player character Sabreman has forty days to collect objects throughout a castle and brew a cure to his werewolf curse. Each castle room is depicted in monochrome on its own screen and consists of blocks to climb, obstacles to avoid, and puzzles to solve.

Ultimate released Knight Lore third in the Sabreman series but later claimed to have completed it first and withheld its release for a year to position the company advantageously in anticipation of the game''s effect on the market. Knight Lore''s novel image masking technique, Filmation, let images appear to pass atop and behind each other without their contents colliding. This created the illusion of depth priority, which the computer did not natively support. By delaying Knight Lore''s release, Ultimate protected sales of their then-upcoming Sabre Wulf and created another Filmation game before other developers could copy the style. Ultimate released the original Sabreman trilogy in quick succession in 1984 for the ZX Spectrum. Knight Lore came last, in November. Ports followed for the BBC Micro, Amstrad CPC, MSX, and Family Computer Disk System.', 'https://en.wikipedia.org/wiki/Knight_Lore'),
  ('Q2705630', 'Super Mario Bros. 2 is a platform game developed and published by Nintendo for the Nintendo Entertainment System. After the smash hit Super Mario Bros. in 1985, Nintendo quickly released an adaptation of the original with advanced difficulty titled Super Mario Bros. 2 for its market in Japan on June 3, 1986. However, Nintendo of America found this sequel too similar to its predecessor, and its difficulty too frustrating, for the nascent American market. This prompted a second Super Mario Bros. sequel based on Yume Kōjō: Doki Doki Panic, a Famicom Disk System game that had been based on a prototype platforming game and released as an advergame for Fuji Television''s Yume Kōjō ''87 media technology expo on July 10, 1987. The characters, enemies, and themes in Doki Doki Panic have the mascots and theme of the festival, and were adapted into the Super Mario theme to make a Western Super Mario Bros. sequel. Super Mario Bros. 2 was released on October 9, 1988, in North America, and was later released in Europe and Australia on April 28, 1989.', 'https://en.wikipedia.org/wiki/Super_Mario_Bros._2'),
  ('Q2866029', 'Arumana no Kiseki is a platform game by Konami for the Family Computer Disk System. It was released in Japan on August 11, 1987.', 'https://en.wikipedia.org/wiki/Arumana_no_Kiseki'),
  ('Q3022851', 'Wardner is a 1987 platform game developed by Toaplan and published by Taito for arcades. Players assume the role of a child named Dover on a journey to rescue his kidnapped girlfriend Mia from the titular warlock. The game was later ported to the Famicom Disk System and Sega Genesis, with both ports featuring several changes and additions compared to the original version. Conversions for both the Nintendo Entertainment System and PC Engine were also in development but never released.

Wardner was met with positive reception from video game magazines since its release in arcades, though reviewers drew comparison with Capcom''s Ghosts ''n Goblins due to its gameplay style, while the Genesis version was met with mixed reviews after launch. As of 2019, the rights to the title are owned by Tatsujin, a company founded in 2017 by former Toaplan member Masahiro Yuge, which is now an affiliate of Japanese arcade manufacturer exA-Arcadia, alongside many other Toaplan IPs.', 'https://en.wikipedia.org/wiki/Wardner_(video_game)'),
  ('Q3197999', 'Knight Move is a puzzle-platform game designed by Tetris creator Alexey Pajitnov and developed by JV Dialog. Based on the knight''s tour sequence in chess, the game has the player take control of a single knight piece that constantly moves in its characteristic L-shaped pattern on a tiled board. The objective of each round is to collect hearts on the board while avoiding holes that are left when the knight lands each tile a set number of times.

JV Dialog, a joint American-Soviet consortium founded in 1987, purchased Knight Move from Pajitnov that same year. The game was published by Nintendo for the Famicom Disk System exclusively in Japan in 1990. It never saw another release, though a sequel titled Knight Moves was published for Microsoft Windows in 1995.', 'https://en.wikipedia.org/wiki/Knight_Move'),
  ('Q3064867', 'F1 Race is a racing video game developed by HAL Laboratory and published by Nintendo for the Famicom in 1984. It had two "Grand Prix" Famicom Disk System sequels and a Game Boy version.', 'https://en.wikipedia.org/wiki/F1_Race'),
  ('Q3155272', 'Ishido: The Way of Stones is a 1990 puzzle video game developed by Publishing International and published by Accolade. It was designed by Michael Feinberg and programmed by Ian Gilman and Michael Sandige. The game''s producer was Brad Fregger, and Brodie Lockard (the designer of the Shanghai video game) contributed with graphics.', 'https://en.wikipedia.org/wiki/Ishido:_The_Way_of_Stones'),
  ('Q3064864', 'F1 Race is a racing video game developed by HAL Laboratory and published by Nintendo for the Famicom in 1984. It had two "Grand Prix" Famicom Disk System sequels and a Game Boy version.', 'https://en.wikipedia.org/wiki/F1_Race'),
  ('Q3482155', 'Shin Onigashima is a 1987 adventure game developed by Nintendo R&D4 and Pax Softnica. It was released by Nintendo on two disk cards for the Famicom Disk System. Shin Onigashima was produced by Shigeru Miyamoto with music by Koji Kondo. The game is the first in the Famicom Mukashibanashi series and was followed by Yūyūki (1989).', 'https://en.wikipedia.org/wiki/Shin_Onigashima'),
  ('Q3357671', 'Otocky is a musical video game developed by SEDIC and released by ASCII Corporation in 1987 for the Family Computer Disk System in Japan. The game was conceived and designed by Toshio Iwai. Natsuki Ozawa endorsed the game.', 'https://en.wikipedia.org/wiki/Otocky'),
  ('Q4907302', 'Raimais is a 1988 maze video game developed and published by Taito for arcades. It was released only in Japan in April 1988. It was designed by Akira Fujita, who previously designed Arkanoid for Taito. The game was ported to the Famicom Disk System under the title Youmais the same year.

It was included as part of the compilation Taito Legends 2 in 2006, marking its first official release in the west. Hamster Corporation released the game as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4 in November 2021.', 'https://en.wikipedia.org/wiki/Raimais'),
  ('Q3815073', 'Kick and Run is a football video game released in 1986 by Taito for arcade and in 1988 for the Famicom Disk System. The Mexico 86 bootleg, produced by Micro Research, was popular in Europe. The game had no sequel, but since 1990 Taito has invested in the Football Champ football video game series. In 2007 it was re-released for the PlayStation 2 in the Taito Memories II Vol.1 collection.', 'https://en.wikipedia.org/wiki/Kick_and_Run'),
  ('Q6154789', 'The Family Computer Disk System (Famicom Disk System) add-on for the Family Computer has a library of 194 officially licensed games during its initial lifespan, 138 of which were not released on the standard Famicom or NES cartridge format plus 6 additional part 2 disks that served as an extension to previously released part 1 disks. Of these, 148 were released exclusively in Japan, and 46 would be released internationally for the Nintendo Entertainment System in some form. Cartridge games for the Famicom and NES are in the list of Nintendo Entertainment System games.', 'https://en.wikipedia.org/wiki/List_of_Famicom_Disk_System_games'),
  ('Q3715533', 'Druid is a hack and slash dungeon crawl developed by Electralyte Software and published by Firebird in 1986 for the Atari 8-bit computers, and Commodore 64. It was also ported to Amstrad CPC, ZX Spectrum, and by Nippon Dexter in 1988 for the MSX, although the MSX port was released in Japan only. Another Japanese port of Druid entitled Druid: Kyōfu no Tobira was made for the Famicom Disk System by Jaleco in 1988. The game was followed by Druid II: Enlightenment and Warlock: The Avenger.', 'https://en.wikipedia.org/wiki/Druid_(video_game)'),
  ('Q5432792', 'Falsion is an on-rail 3D shoot-''em-up produced by Konami that was released for the Family Computer Disk System on October 21, 1987, in Japan. It is one of the few games compatible with the Famicom 3D System peripheral.', 'https://en.wikipedia.org/wiki/Falsion'),
  ('Q5245447', 'Dead Zone is a text-based adventure video game developed and published by Sunsoft for the Famicom Disk System in Japan on November 20, 1986.', 'https://en.wikipedia.org/wiki/Dead_Zone_(video_game)'),
  ('Q6428747', 'Konami''s Ping Pong is a 1985 sports video game developed and published by Konami for arcades. It is the first video game to accurately reflect the gameplay of table tennis, as opposed to earlier simplifications like Pong. It was released in Japan in May 1985. It was ported to the Amstrad CPC, Commodore 64, Famicom Disk System, MSX, and ZX Spectrum.', 'https://en.wikipedia.org/wiki/Konami%27s_Ping_Pong'),
  ('Q7647299', 'Kinnikuman is a Japanese manga series created by the duo Yoshinori Nakai and Takashi Shimada, known as Yudetamago. It follows Suguru Kinniku, a superhero who must win a wrestling tournament to retain the title of prince of Planet Kinniku. Nakai and Takashi planned the series when they were attending high school originally as a parody to Ultraman.

The manga was originally published in Shueisha''s shōnen manga magazine Weekly Shōnen Jump from 1979 to 1987, and was first adapted by Toei Animation into a 137-episode anime series broadcast on Nippon Television for three seasons from 1983 to 1986, with the final arc being adapted in 1991 as a fourth season. It restarted publication in 2011 in Shueisha''s web magazine Shū Play News, and has spawned spin-off manga and anime series, video games, anime films, and several Kinnikuman-related merchandise.', 'https://en.wikipedia.org/wiki/Kinnikuman'),
  ('Q6352793', 'Kalin no Tsurugi is an action-RPG developed by Xtalsoft and published by Square''s publishing label Disk Original Group (DOG) for the Family Computer Disk System in Japan in 1987.', 'https://en.wikipedia.org/wiki/Kalin_no_Tsurugi'),
  ('Q7635526', 'Suishō no Dragon is an adventure video game developed and published by Square for the Family Computer Disk System in Japan in 1986.', 'https://en.wikipedia.org/wiki/Suish%C5%8D_no_Dragon'),
  ('Q6960387', 'Nakayama Miho no Tokimeki High School is a 1987 adventure game developed by Square and Nintendo R&D1, and published by Nintendo exclusively in Japan for the Family Computer Disk System. The game was released on December 1, 1987, and is one of the first dating sim video games. It was designed by Hironobu Sakaguchi, who also created the Final Fantasy series, and Yoshio Sakamoto, who co-created Metroid. The music for the game was composed by Nobuo Uematsu and Toshiaki Imai. Pop idol Miho Nakayama contributed her name and likeness and voice-acted tie-in segments that could be accessed by calling toll-free phone numbers revealed during the progress of gameplay.', 'https://en.wikipedia.org/wiki/Nakayama_Miho_no_Tokimeki_High_School'),
  ('Q7335808', 'Risa no Yōsei Densetsu is a Family Computer Disk System game, released in 1988. It stars the Japanese idol Risa Tachibana.', 'https://en.wikipedia.org/wiki/Risa_no_Y%C5%8Dsei_Densetsu'),
  ('Q7805184', 'Time Twist: Rekishi no Katasumi de... is a 1991 adventure game developed by Nintendo and Pax Softnica and published by Nintendo for the Family Computer Disk System. Known for its disturbing subject matter, including allusions to real life atrocities and religion, it was never released outside of Japan.', 'https://en.wikipedia.org/wiki/Time_Twist:_Rekishi_no_Katasumi_de...'),
  ('Q8062794', 'Famicom Mukashibanashi: Yūyūki, often simply titled as Yūyūki, is a 1989 text-based adventure game developed by Nintendo R&D4 and Pax Softnica. It was released by Nintendo on two disk cards for the Famicom Disk System. Yūyūki is the second in the Famicom Mukashibanashi series after Shin Onigashima (1987). The game is loosely based on the Chinese novel Journey to the West.', 'https://en.wikipedia.org/wiki/Y%C5%ABy%C5%ABki'),
  ('Q11291191', 'Electrician is a platform game written by David Bunch for Atari 8-bit computers and published by Synapse Software in 1984. Synapse sold the game as a "Double Play", with the game New York City on one side of the floppy disk, and Electrician on the other. Kemco adapted the game for the Family Computer Disk System, and republished it in 1986.

David Bunch later co-designed the 1988 game Skate or Die!.', 'https://en.wikipedia.org/wiki/Electrician_(video_game)'),
  ('Q11299567', 'Cleopatra no Mahō is a role-playing video game developed and published by Square for the Family Computer Disk System, and released in Japan on 24 July 1987. The game''s music was composed by Nobuo Uematsu.', 'https://en.wikipedia.org/wiki/Cleopatra_no_Mah%C5%8D'),
  ('Q631331', 'Super Mario Bros. 2, known outside of Japan as Super Mario Bros.: The Lost Levels, is a 1986 platform game developed by Nintendo R&D4 for the Famicom Disk System. Like its predecessor, Super Mario Bros., players control Mario or Luigi to rescue Princess Peach from Bowser. The Lost Levels has a higher difficulty level, introducing obstacles such as the Poison Mushroom, counterproductive level warps and mid-air wind gusts. Luigi controls differently from Mario, with reduced ground friction and increased jump height. The game contains 32 levels across eight worlds, and 20 bonus levels.

Nintendo developed The Lost Levels after designing some of its levels for the Nintendo VS. System version of Super Mario Bros. It was directed by Takashi Tezuka and designed for players who had mastered the original. Nintendo released it as Super Mario Bros. 2 in Japan on June 3, 1986, but Nintendo of America deemed it too difficult and too similar to Super Mario Bros. for the North American market and released an alternative Super Mario Bros. 2 (1988) instead. The original Super Mario Bros. 2 was retitled The Lost Levels for its inclusion in the 1993 Super Nintendo Entertainment System compilation Super Mario All-Stars, its first international release. It has been rereleased for Game Boy Color, Game Boy Advance, Wii, Wii U, Nintendo 3DS, and Nintendo Switch.', 'https://en.wikipedia.org/wiki/Super_Mario_Bros.:_The_Lost_Levels');

update public.game g
set summary_en = i.summary, summary_en_source = i.source
from import_summary i
where g.wikidata_id = i.wikidata_id
  and g.summary_en is null;

drop table import_summary;
